#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int v[505];
    int present[505] = {0};
    int distinct[505];
    int num_distinct = 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
        if (!present[v[i]]) {
            present[v[i]] = 1;
            distinct[num_distinct++] = v[i];
        }
    }

    if (num_distinct <= 2) {
        // Se há 1 ou 2 valores distintos, apenas removemos adjacentes repetidos
        int ans = 0;
        int last = 0;
        for (int i = 0; i < n; i++) {
            if (v[i] != last) {
                ans++;
                last = v[i];
            }
        }
        printf("%d\n", ans);
        return 0;
    }

    int max_len = 1;

    for (int i = 0; i < num_distinct; i++) {
        for (int j = i + 1; j < num_distinct; j++) {
            int a = distinct[i];
            int b = distinct[j];
            int count = 0;
            int last = 0;

            for (int k = 0; k < n; k++) {
                if (v[k] == a || v[k] == b) {
                    if (v[k] != last) {
                        count++;
                        last = v[k];
                    }
                }
            }

            if (count > max_len) {
                max_len = count;
            }
        }
    }

    printf("%d\n", max_len);

    return 0;
}
